(()=>{'use strict';const $=s=>document.querySelector(s),canvas=$('#game'),ctx=canvas.getContext('2d'),W=960,H=540;ctx.imageSmoothingEnabled=false;const ui={lobby:$('#lobby'),waiting:$('#waiting'),end:$('#end'),room:$('#roomText'),time:$('#timeText'),coins:$('#coinText'),boss:$('#bossText'),notice:$('#notice'),party:$('#party'),big:$('#bigCode'),connection:$('#connectionText')};let ws,state=null,myId=null,room=null,sound=true,audio=null,noticeTimer,last=0;const keys=new Set(),fmt=n=>`${String(Math.floor((n||0)/60)).padStart(2,'0')}:${String(Math.floor((n||0)%60)).padStart(2,'0')}`;
function beep(f=340,d=.05){if(!sound)return;try{audio||=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.value=f;g.gain.value=.025;o.connect(g).connect(audio.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.stop(audio.currentTime+d)}catch{}}
function connect(){ui.connection.textContent='성문 서버에 연결 중…';ws=new WebSocket(window.GAME_SERVER_URL);ws.onopen=()=>{ui.connection.textContent='● 성문 서버 연결됨';ui.connection.className='connection';const q=new URLSearchParams(location.search).get('room');if(q)$('#codeInput').value=q.toUpperCase()};ws.onclose=()=>{ui.connection.textContent='서버 연결이 끊겼습니다. 다시 연결 중…';ui.connection.className='connection bad';setTimeout(connect,1800)};ws.onerror=()=>ws.close();ws.onmessage=e=>handle(JSON.parse(e.data))}function send(type,data={}){if(ws?.readyState===1)ws.send(JSON.stringify({type,...data}))}
function handle(m){if(m.type==='joined'){myId=m.playerId;room=m.room;ui.room.textContent=room;ui.big.textContent=room;show(ui.waiting);history.replaceState(null,'',`?room=${room}`)}if(m.type==='state'){state=m.state;room=state.code;syncUI();if(state.phase==='playing')hideAll();if(state.phase==='ended')showEnd()}if(m.type==='error'||m.type==='notice')flash(m.message)}function name(){return $('#nameInput').value.trim()||`기사${Math.floor(Math.random()*90+10)}`}function show(el){hideAll();el.classList.add('visible')}function hideAll(){[ui.lobby,ui.waiting,ui.end].forEach(x=>x.classList.remove('visible'))}function flash(t){ui.notice.textContent=t;ui.notice.classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>ui.notice.classList.remove('visible'),2200);beep(180,.12)}
function syncUI(){if(!state)return;ui.time.textContent=fmt(state.elapsed);ui.coins.textContent=String(state.coins).padStart(3,'0');ui.boss.textContent=`${Math.max(0,state.bossHp)}%`;ui.party.innerHTML=state.players.map(p=>`<div class="party-member"><span>${p.name}${p.id===state.hostId?' · 방장':''}</span><b>${p.alive?'준비 완료':'쓰러짐'}</b></div>`).join('');$('#startBtn').style.display=myId===state.hostId?'block':'none'}function showEnd(){if(!ui.end.classList.contains('visible')){show(ui.end);const win=state.result==='win';$('#endKicker').textContent=win?'THE FLAME ENDURES':'THE CASTLE HAS FALLEN';$('#endTitle').textContent=win?'우리 모두의 승리!':'불꽃이 꺼졌습니다';$('#endText').textContent=win?`${fmt(state.elapsed)} 동안 함께 싸워 검은 성을 지켰습니다.`:'동료와 다시 힘을 모아 도전하세요.';beep(win?760:90,.5)}}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}function castle(){rect(0,0,W,H,'#080a10');for(let i=0;i<70;i++){const x=i*137%W,y=i*83%310;rect(x,y,2,2,i%5?'#191a24':'#6e685d')}rect(0,325,W,215,'#191a20');ctx.strokeStyle='#342f34';ctx.lineWidth=2;for(let y=330;y<540;y+=28)for(let x=(y/28%2)*-35;x<W;x+=70)ctx.strokeRect(x,y,68,26);rect(36,240,210,150,'#231b1d');rect(26,230,230,20,'#100f13');ctx.fillStyle='#18131a';ctx.beginPath();ctx.moveTo(18,230);ctx.lineTo(141,148);ctx.lineTo(264,230);ctx.fill();for(let y=253;y<390;y+=22)for(let x=42+(y/22%2)*14;x<235;x+=44){ctx.strokeStyle='#4a3030';ctx.strokeRect(x,y,42,20)}rect(99,308,55,82,'#0b0a0d');rect(179,274,34,34,'#6f3f28');rect(184,279,24,24,'#ff9b3e');for(const [x,y]of[[70,415],[278,365],[360,428],[730,390]]){rect(x,y,8,28,'#d5b87e');ctx.fillStyle='#ff9b3e';ctx.beginPath();ctx.moveTo(x+4,y-13);ctx.lineTo(x+10,y);ctx.lineTo(x+4,y+5);ctx.lineTo(x-2,y);ctx.fill();ctx.globalAlpha=.12;ctx.beginPath();ctx.arc(x+4,y,34,0,6.28);ctx.fill();ctx.globalAlpha=1}}
function rider(p){ctx.save();ctx.translate(p.x,p.y);if(!p.alive)ctx.globalAlpha=.35;rect(-15,7,32,13,'#49352d');rect(-10,19,6,13,'#241d1c');rect(8,19,6,13,'#241d1c');rect(12,1,14,10,'#49352d');rect(-6,-14,15,20,p.color);rect(-4,-27,12,12,'#c29b78');rect(-7,-31,18,6,'#25232a');if(!p.alive){ctx.globalAlpha=1;ctx.strokeStyle='#d5b87e';ctx.strokeRect(-23,-38,46,70)}ctx.restore()}function monster(){const hp=state?.bossHp??100;ctx.save();ctx.translate(867,270);rect(-47,-92,78,186,'#272d26');rect(-59,-55,23,65,'#343c31');rect(-31,-108,55,48,'#394438');rect(-22,-92,11,10,'#f5c86e');rect(4,-92,11,10,'#f5c86e');rect(-19,-88,5,5,'#0a0808');rect(7,-88,5,5,'#0a0808');rect(-18,-68,30,7,'#8f3c31');rect(-45,-120,80,7,'#131419');rect(-45,-120,80*(hp/100),7,'#a13b30');ctx.restore()}function arrow(a){ctx.save();ctx.translate(a.x,a.y);ctx.rotate(Math.atan2(a.vy,a.vx));rect(-18,-2,30,4,'#796750');ctx.fillStyle='#b54235';ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(8,-7);ctx.lineTo(8,7);ctx.fill();ctx.restore()}
function draw(){castle();monster();if(state){for(const c of state.pickups||[]){ctx.fillStyle='#e5aa3e';ctx.beginPath();ctx.arc(c.x,c.y,9,0,7);ctx.fill()}for(const a of state.arrows||[])arrow(a);for(const s of state.shots||[])rect(s.x-8,s.y-2,18,4,'#e1c37e');for(const p of state.players)rider(p);if(state.phase==='playing'&&state.players.some(p=>!p.alive)){ctx.fillStyle='#d8c39e';ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText('쓰러진 동료 곁을 지키면 부활합니다',W/2,28);ctx.textAlign='left'}}}function input(){if(!state||state.phase!=='playing')return;const x=(keys.has('ArrowRight')||keys.has('KeyD')?1:0)-(keys.has('ArrowLeft')||keys.has('KeyA')?1:0),y=(keys.has('ArrowDown')||keys.has('KeyS')?1:0)-(keys.has('ArrowUp')||keys.has('KeyW')?1:0),shoot=keys.has('Space')||keys.has('ShiftLeft')||keys.has('ShiftRight');send('input',{x,y,shoot})}function loop(t){if(t-last>45){input();last=t}draw();requestAnimationFrame(loop)}
$('#createBtn').onclick=()=>send('create',{name:name()});$('#joinBtn').onclick=()=>send('join',{name:name(),code:$('#codeInput').value.trim().toUpperCase()});$('#startBtn').onclick=()=>send('start');$('#againBtn').onclick=()=>send('restart');$('#leaveBtn').onclick=()=>location.href=location.pathname;$('#copyBtn').onclick=async()=>{await navigator.clipboard.writeText(`${location.origin}${location.pathname}?room=${room}`);flash('초대 주소를 복사했습니다')};$('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn').textContent=sound?'♪ 소리 켬':'× 소리 끔';beep(600)};addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys.add(e.code)});addEventListener('keyup',e=>keys.delete(e.code));connect();requestAnimationFrame(loop)})();
